preConditionHook:
// RED RUN THROUGH STACKED SUPPORT, FADED (Brian's notes ON-26, #26, p.28;
// reading confirmed by Brian 2026-11-05). Two DISTINCT, STACKED I2 support
// zones (below) are valid as of the bar before the run. An unbroken run of red
// bars (close < open) ends at this bar, at most maxRunBars long; its first bar
// opened at or above the upper zone's bottom (inside the zone counts as "at"),
// and this bar, still red, is the FIRST in the run to close below the lower
// zone's bottom: long, a fade. Short mirrors: a green run up through two
// stacked resistance zones, first close above the upper zone's top. The range
// precondition is a separate pane-2 rule (I3 / I1).
//
// THE TWO ZONES. Each window of zoneSize consecutive swing lows is the I2
// zone as it stood when its newest member formed; it is valid when it passes
// the width and spread tests and no close since its newest member, up to the
// reference bar, killed it. Zone 1 is the most recent valid window; zone 2 is
// the most recent valid window whose price range does not overlap zone 1's
// (strictly above or below it) -- "two distinct zones" (Brian 2026-11-05).
// Price-disjoint implies member-disjoint, since a shared member would lie in
// both ranges. The reference bar is the bar before the run (bars-ago runK):
// candidates at runK + zoneStrength .. runK + pivotLookback - 1, the kill
// check over closes at bars-ago runK + 1 .. the newest member (I2's own
// 1 .. newest, shifted). The ATR is the current bar's.
//
//
// I2 SUPPORT ZONE (Brian's indicator 20250116.1, settled 2026-11-05), inlined.
// A support zone is M (zoneSize) CONSECUTIVE swing lows (consecutive in the swing-low
// sequence) of strength S (zoneStrength), non-alternating, that all lie within W (zoneWidthAtr) ATRs of each
// other (max - min <= W x ATR) and whose POPULATION standard deviation is at
// most K (zoneStdAtr) ATRs -- Brian's spread test, replacing the identically-zero
// horizontal-line R^2. Bottom = the lowest of them, top = the highest. A close
// more than a margin (zoneKillAtr) of ATRs below the bottom kills it. Resistance mirrors:
// swing highs, killed by a close more than the margin above the top. Sums run
// newest-first, mean first and squared deviations second (two passes). The
// members are found by re-scanning the window, because EasyLanguage arrays
// have no row in the register. Pivot test hand-rolled as in SwingPivotTarget
// (EL_Swing_Probe.txt): AT OR ABOVE the S OLDER bars, STRICTLY ABOVE the S
// NEWER bars (the smaller index), lag exactly S; the low side mirrors. No
// Break -- not a registered word.
//
// Scratch below is declared in localVariables, not at hook scope: the
// generator only prefixes declared locals, so a hook-scope declaration
// is a redefinition when this rule is placed twice in one strategy.
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and updated
// thereafter as TWO statements -- EL evaluates S[1] + in - out left to right,
// and folding it to S += in - out rounds differently. The local counter is
// atrLen, not the input.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
fireL = false;
fireS = false;
// long: red run down through two support zones
runK = 0;
runOn = true;
for (int jj = 0; jj <= (int)maxRunBars; ++jj) {
    if (el_ge(close[jj], open[jj])) runOn = false;
    if (runOn) runK = runK + 1;
}
if (runK >= 1 && runK <= (int)maxRunBars) {
    z1Found = false;
    z2Found = false;
    for (int jj = runK + (int)zoneStrength; jj <= runK + (int)pivotLookback - 1; ++jj) {
        okP = true;
        for (int mm = jj - (int)zoneStrength; mm <= jj - 1; ++mm) {
            if (el_ge(low[jj], low[mm])) okP = false;
        }
        for (int mm = jj + 1; mm <= jj + (int)zoneStrength; ++mm) {
            if (el_gt(low[jj], low[mm])) okP = false;
        }
        if (okP && !z2Found) {
            wN = 0;
            wMin = 0.0;
            wMax = 0.0;
            wSum = 0.0;
            wOld = jj;
            for (int kk = jj; kk <= runK + (int)pivotLookback - 1; ++kk) {
                okQ = true;
                for (int mm = kk - (int)zoneStrength; mm <= kk - 1; ++mm) {
                    if (el_ge(low[kk], low[mm])) okQ = false;
                }
                for (int mm = kk + 1; mm <= kk + (int)zoneStrength; ++mm) {
                    if (el_gt(low[kk], low[mm])) okQ = false;
                }
                if (okQ && wN < (int)zoneSize) {
                    wN = wN + 1;
                    if (wN == 1) {
                        wMin = low[kk];
                        wMax = low[kk];
                    }
                    if (el_lt(low[kk], wMin)) wMin = low[kk];
                    if (el_gt(low[kk], wMax)) wMax = low[kk];
                    wSum = wSum + low[kk];
                    wOld = kk;
                }
            }
            wOk = false;
            if (wN >= 1 && wN == (int)zoneSize) {
                wMu = wSum / wN;
                wSS = 0.0;
                for (int kk = jj; kk <= wOld; ++kk) {
                    okQ = true;
                    for (int mm = kk - (int)zoneStrength; mm <= kk - 1; ++mm) {
                        if (el_ge(low[kk], low[mm])) okQ = false;
                    }
                    for (int mm = kk + 1; mm <= kk + (int)zoneStrength; ++mm) {
                        if (el_gt(low[kk], low[mm])) okQ = false;
                    }
                    if (okQ) wSS = wSS + (low[kk] - wMu) * (low[kk] - wMu);
                }
                wOk = el_le(wMax - wMin, zoneWidthAtr * atrVal) && el_le(std::sqrt(wSS / wN), zoneStdAtr * atrVal);
                for (int kk = runK + 1; kk <= jj; ++kk) {
                    if (el_lt(close[kk], wMin - zoneKillAtr * atrVal)) wOk = false;
                }
            }
            if (wOk && z1Found && (el_lt(wMax, z1Lo) || el_gt(wMin, z1Hi))) {
                z2Found = true;
                z2Lo = wMin;
                z2Hi = wMax;
            }
            if (wOk && !z1Found) {
                z1Found = true;
                z1Lo = wMin;
                z1Hi = wMax;
            }
        }
    }
    if (z2Found) {
        zULo = z1Lo;
        zUHi = z1Hi;
        zLLo = z2Lo;
        zLHi = z2Hi;
        if (el_gt(z2Lo, z1Lo)) {
            zULo = z2Lo;
            zUHi = z2Hi;
            zLLo = z1Lo;
            zLHi = z1Hi;
        }
        if (el_ge(open[runK - 1], zULo) && el_lt(close[0], zLLo) && (runK == 1 || el_ge(close[1], zLLo))) fireL = true;
    }
}
// short: green run up through two resistance zones
runK = 0;
runOn = true;
for (int jj = 0; jj <= (int)maxRunBars; ++jj) {
    if (el_le(close[jj], open[jj])) runOn = false;
    if (runOn) runK = runK + 1;
}
if (runK >= 1 && runK <= (int)maxRunBars) {
    z1Found = false;
    z2Found = false;
    for (int jj = runK + (int)zoneStrength; jj <= runK + (int)pivotLookback - 1; ++jj) {
        okP = true;
        for (int mm = jj - (int)zoneStrength; mm <= jj - 1; ++mm) {
            if (el_le(high[jj], high[mm])) okP = false;
        }
        for (int mm = jj + 1; mm <= jj + (int)zoneStrength; ++mm) {
            if (el_lt(high[jj], high[mm])) okP = false;
        }
        if (okP && !z2Found) {
            wN = 0;
            wMin = 0.0;
            wMax = 0.0;
            wSum = 0.0;
            wOld = jj;
            for (int kk = jj; kk <= runK + (int)pivotLookback - 1; ++kk) {
                okQ = true;
                for (int mm = kk - (int)zoneStrength; mm <= kk - 1; ++mm) {
                    if (el_le(high[kk], high[mm])) okQ = false;
                }
                for (int mm = kk + 1; mm <= kk + (int)zoneStrength; ++mm) {
                    if (el_lt(high[kk], high[mm])) okQ = false;
                }
                if (okQ && wN < (int)zoneSize) {
                    wN = wN + 1;
                    if (wN == 1) {
                        wMin = high[kk];
                        wMax = high[kk];
                    }
                    if (el_lt(high[kk], wMin)) wMin = high[kk];
                    if (el_gt(high[kk], wMax)) wMax = high[kk];
                    wSum = wSum + high[kk];
                    wOld = kk;
                }
            }
            wOk = false;
            if (wN >= 1 && wN == (int)zoneSize) {
                wMu = wSum / wN;
                wSS = 0.0;
                for (int kk = jj; kk <= wOld; ++kk) {
                    okQ = true;
                    for (int mm = kk - (int)zoneStrength; mm <= kk - 1; ++mm) {
                        if (el_le(high[kk], high[mm])) okQ = false;
                    }
                    for (int mm = kk + 1; mm <= kk + (int)zoneStrength; ++mm) {
                        if (el_lt(high[kk], high[mm])) okQ = false;
                    }
                    if (okQ) wSS = wSS + (high[kk] - wMu) * (high[kk] - wMu);
                }
                wOk = el_le(wMax - wMin, zoneWidthAtr * atrVal) && el_le(std::sqrt(wSS / wN), zoneStdAtr * atrVal);
                for (int kk = runK + 1; kk <= jj; ++kk) {
                    if (el_gt(close[kk], wMax + zoneKillAtr * atrVal)) wOk = false;
                }
            }
            if (wOk && z1Found && (el_lt(wMax, z1Lo) || el_gt(wMin, z1Hi))) {
                z2Found = true;
                z2Lo = wMin;
                z2Hi = wMax;
            }
            if (wOk && !z1Found) {
                z1Found = true;
                z1Lo = wMin;
                z1Hi = wMax;
            }
        }
    }
    if (z2Found) {
        zULo = z1Lo;
        zUHi = z1Hi;
        zLLo = z2Lo;
        zLHi = z2Hi;
        if (el_gt(z2Lo, z1Lo)) {
            zULo = z2Lo;
            zUHi = z2Hi;
            zLLo = z1Lo;
            zLHi = z1Hi;
        }
        if (el_le(open[runK - 1], zLHi) && el_gt(close[0], zUHi) && (runK == 1 || el_le(close[1], zUHi))) fireS = true;
    }
}
